CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL UNIQUE,name text NOT NULL,position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY member_categories ON public.categories FOR SELECT TO authenticated USING(true);
CREATE TABLE public.custom_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),normalized text NOT NULL UNIQUE,label text NOT NULL);
GRANT SELECT ON public.custom_categories TO authenticated; GRANT ALL ON public.custom_categories TO service_role; ALTER TABLE public.custom_categories ENABLE ROW LEVEL SECURITY; CREATE POLICY admin_custom_categories ON public.custom_categories FOR SELECT TO authenticated USING(public.is_admin());
ALTER TABLE public.items ADD COLUMN custom_category text NOT NULL DEFAULT '',ADD COLUMN category_id uuid REFERENCES public.categories(id),ADD COLUMN custom_category_id uuid REFERENCES public.custom_categories(id);
ALTER TABLE public.wishes ADD COLUMN custom_category text NOT NULL DEFAULT '',ADD COLUMN category_id uuid REFERENCES public.categories(id),ADD COLUMN custom_category_id uuid REFERENCES public.custom_categories(id);
ALTER TABLE public.synonyms ADD COLUMN category_id uuid REFERENCES public.categories(id);
ALTER TABLE public.items DROP CONSTRAINT items_category_check; ALTER TABLE public.wishes DROP CONSTRAINT wishes_category_check;
ALTER TABLE public.profiles ADD COLUMN pickup_times text[] NOT NULL DEFAULT '{}',ADD COLUMN claim_emails boolean NOT NULL DEFAULT true,ADD COLUMN message_emails boolean NOT NULL DEFAULT true;
CREATE FUNCTION public.custom_category_key(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT string_agg(CASE WHEN length(w)>3 AND right(w,1)='s' AND right(w,2)<>'ss' THEN left(w,length(w)-1) ELSE w END,' ' ORDER BY n) FROM regexp_split_to_table(lower(trim(public.clean_text(t))),'\s+') WITH ORDINALITY AS x(w,n) WHERE w<>'' $$;
CREATE FUNCTION public.category_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cat public.categories; BEGIN IF lower(NEW.category)='other' THEN NEW.category='other'; NEW.custom_category=public.clean_text(coalesce(nullif(current_setting('passalong.custom_category',true),''),NEW.custom_category)); IF length(NEW.custom_category) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'Custom categories must be 1–30 characters'; END IF; INSERT INTO public.custom_categories(normalized,label) VALUES(public.custom_category_key(NEW.custom_category),NEW.custom_category) ON CONFLICT(normalized) DO UPDATE SET normalized=excluded.normalized RETURNING id INTO NEW.custom_category_id; SELECT * INTO cat FROM public.categories WHERE key='other'; ELSE SELECT * INTO cat FROM public.categories WHERE key=NEW.category; IF cat.id IS NULL THEN RAISE EXCEPTION 'Choose a category'; END IF; NEW.custom_category=''; NEW.custom_category_id=NULL; END IF; NEW.category_id=cat.id; RETURN NEW; END $$;
CREATE TRIGGER items_category_guard BEFORE INSERT OR UPDATE OF category,custom_category ON public.items FOR EACH ROW EXECUTE FUNCTION public.category_guard(); CREATE TRIGGER wishes_category_guard BEFORE INSERT OR UPDATE OF category,custom_category ON public.wishes FOR EACH ROW EXECUTE FUNCTION public.category_guard();
CREATE FUNCTION public.synonym_category_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT id INTO NEW.category_id FROM public.categories WHERE key=NEW.category; IF NEW.category_id IS NULL THEN RAISE EXCEPTION 'Choose a category'; END IF; RETURN NEW; END $$; CREATE TRIGGER synonyms_category_guard BEFORE INSERT OR UPDATE OF category ON public.synonyms FOR EACH ROW EXECUTE FUNCTION public.synonym_category_guard();
ALTER TABLE public.events ADD COLUMN category_id uuid; ALTER TABLE public.events DROP CONSTRAINT events_name_check; ALTER TABLE public.events ADD CONSTRAINT events_name_check CHECK(name IN('circle_link_opened','item_link_opened','signed_up','joined_circle','wish_added','item_posted','post_nudge_shown','item_shared','match_created','match_notification_sent','swipe_right','swipe_left','item_claimed','pickup_arranged','picked_up','thanked','claim_expired','item_expired','item_renewed','item_marked_donated','notify_me_tapped','clearout_interest_yes','clearout_interest_no','circle_created','circle_search_opened','circle_join_requested','circle_join_approved','circle_joined_from_search','circle_left','member_removed','profile_updated','custom_category_used','category_promoted'));
CREATE FUNCTION public.category_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.category='other' THEN INSERT INTO public.events(user_id,item_id,circle_id,name,category_id) VALUES(CASE WHEN TG_TABLE_NAME='items' THEN (to_jsonb(NEW)->>'giver_id')::uuid ELSE (to_jsonb(NEW)->>'user_id')::uuid END,CASE WHEN TG_TABLE_NAME='items' THEN NEW.id ELSE NULL END,NEW.circle_id,'custom_category_used',NEW.custom_category_id); END IF; RETURN NEW; END $$;
CREATE TRIGGER item_custom_event AFTER INSERT ON public.items FOR EACH ROW EXECUTE FUNCTION public.category_event(); CREATE TRIGGER wish_custom_event AFTER INSERT ON public.wishes FOR EACH ROW EXECUTE FUNCTION public.category_event(); CREATE TRIGGER custom_item_match AFTER UPDATE OF custom_category ON public.items FOR EACH STATEMENT EXECUTE FUNCTION public.recalculate_matches(); CREATE TRIGGER custom_wish_match AFTER UPDATE OF custom_category,category ON public.wishes FOR EACH STATEMENT EXECUTE FUNCTION public.recalculate_matches();
CREATE OR REPLACE FUNCTION public.profile_detail_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.bio=public.clean_text(NEW.bio); NEW.general_area=public.clean_text(NEW.general_area); IF length(NEW.bio)>160 OR NOT public.safe_general_area(NEW.general_area) THEN RAISE EXCEPTION 'Use a bio up to 160 characters and a general area, not an address'; END IF; IF NOT NEW.pickup_times <@ ARRAY['Weekday mornings','Weekday evenings','Weekends','Flexible'] THEN RAISE EXCEPTION 'Choose a pickup preference'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.member_display_name(t text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN cardinality(parts)>1 THEN parts[1]||' '||left(parts[cardinality(parts)],1)||'.' ELSE parts[1] END FROM (SELECT regexp_split_to_array(trim(public.clean_text(t)),'\s+') parts) x $$;
CREATE OR REPLACE FUNCTION public.member_names(circle uuid) RETURNS TABLE(id uuid,display_name text,avatar_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,CASE WHEN p.id=auth.uid() THEN p.display_name ELSE public.member_display_name(p.display_name) END,p.avatar_url FROM public.profiles p JOIN public.circle_members cm ON cm.user_id=p.id WHERE cm.circle_id=circle AND cm.status='active' AND public.is_member(circle) $$;
CREATE OR REPLACE FUNCTION public.circle_members_detail(circle uuid) RETURNS TABLE(id uuid,display_name text,avatar_url text,bio text,general_area text,joined_at timestamptz,role text,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,CASE WHEN p.id=auth.uid() THEN p.display_name ELSE public.member_display_name(p.display_name) END,p.avatar_url,p.bio,p.general_area,cm.joined_at,cm.role,cm.status FROM public.circle_members cm JOIN public.profiles p ON p.id=cm.user_id JOIN public.circles c ON c.id=cm.circle_id WHERE cm.circle_id=circle AND public.is_member(circle) AND (cm.status='active' OR c.owner_id=auth.uid() OR public.is_admin()) $$;
CREATE TABLE public.kind_words(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL UNIQUE REFERENCES public.claims(id),writer_id uuid NOT NULL REFERENCES public.profiles(id),giver_id uuid NOT NULL REFERENCES public.profiles(id),text text NOT NULL,show_on_profile boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kind_words TO authenticated; GRANT ALL ON public.kind_words TO service_role; ALTER TABLE public.kind_words ENABLE ROW LEVEL SECURITY;
CREATE POLICY kind_words_read ON public.kind_words FOR SELECT TO authenticated USING(writer_id=auth.uid() OR show_on_profile AND (giver_id=auth.uid() OR EXISTS(SELECT 1 FROM public.circle_members a JOIN public.circle_members b ON b.circle_id=a.circle_id WHERE a.user_id=auth.uid() AND b.user_id=giver_id AND a.status='active' AND b.status='active')));
CREATE FUNCTION public.member_profile(member uuid,circle uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; BEGIN IF NOT public.is_member(circle) OR NOT EXISTS(SELECT 1 FROM public.circle_members WHERE circle_id=circle AND user_id=member AND status='active') THEN RETURN NULL; END IF; SELECT * INTO p FROM public.profiles WHERE id=member; RETURN jsonb_build_object('id',p.id,'display_name',public.member_display_name(p.display_name),'avatar_url',p.avatar_url,'bio',p.bio,'general_area',p.general_area,'shared_circles',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name)),'[]') FROM public.circles c WHERE public.is_member(c.id) AND EXISTS(SELECT 1 FROM public.circle_members m WHERE m.circle_id=c.id AND m.user_id=member AND m.status='active')),'passed_along',(SELECT count(*) FROM public.claims cl JOIN public.items i ON i.id=cl.item_id WHERE cl.status IN('picked_up','thanked') AND (i.giver_id=member OR cl.receiver_id=member)),'kind_words',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',k.id,'text',k.text,'writer_name',public.member_display_name(w.display_name)) ORDER BY k.created_at DESC),'[]') FROM public.kind_words k JOIN public.profiles w ON w.id=k.writer_id WHERE k.giver_id=member AND k.show_on_profile)); END $$;
REVOKE ALL ON FUNCTION public.member_profile(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.member_profile(uuid,uuid) TO authenticated;
CREATE FUNCTION public.category_admin_data() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',cc.id,'label',cc.label,'count',(SELECT count(*) FROM public.items i WHERE i.custom_category_id=cc.id)+(SELECT count(*) FROM public.wishes w WHERE w.custom_category_id=cc.id))),'[]') FROM public.custom_categories cc WHERE EXISTS(SELECT 1 FROM public.items i WHERE i.custom_category_id=cc.id) OR EXISTS(SELECT 1 FROM public.wishes w WHERE w.custom_category_id=cc.id)); END $$;
CREATE FUNCTION public.category_action(action text,payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; key_value text; label_value text=public.clean_text(payload->>'name'); cc public.custom_categories; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF; IF action IN('add','rename','promote') AND length(label_value) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'Category names must be 1–50 characters'; END IF;
IF action IN('add','promote') THEN key_value='category-'||gen_random_uuid()::text; INSERT INTO public.categories(key,name,position) VALUES(key_value,label_value,(SELECT coalesce(max(position),0)+1 FROM public.categories)) RETURNING id INTO cid; IF action='promote' THEN SELECT * INTO cc FROM public.custom_categories WHERE id=(payload->>'id')::uuid FOR UPDATE; IF cc.id IS NULL THEN RAISE EXCEPTION 'Custom category not found'; END IF; UPDATE public.items SET category=key_value,custom_category='' WHERE custom_category_id=cc.id; UPDATE public.wishes SET category=key_value,custom_category='' WHERE custom_category_id=cc.id; INSERT INTO public.events(user_id,name,category_id) VALUES(auth.uid(),'category_promoted',cid); END IF;
ELSIF action='rename' THEN UPDATE public.categories SET name=label_value WHERE id=(payload->>'id')::uuid AND key<>'other';
ELSIF action='reorder' THEN UPDATE public.categories SET position=x.n::integer FROM jsonb_array_elements_text(payload->'ids') WITH ORDINALITY x(id,n) WHERE categories.id=x.id::uuid;
ELSE RAISE EXCEPTION 'Unknown category action'; END IF; RETURN jsonb_build_object('id',cid); END $$;
REVOKE ALL ON FUNCTION public.category_admin_data(),public.category_action(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.category_admin_data(),public.category_action(text,jsonb) TO authenticated;
DO $migration$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.passalong_action(text,jsonb)'::regprocedure) INTO body; body=replace(body,'public.passalong_action(','public.passalong_circle_action('); EXECUTE body; END $migration$;
REVOKE ALL ON FUNCTION public.passalong_circle_action(text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.passalong_circle_action(text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.passalong_action(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF action='profile' THEN UPDATE public.profiles SET pickup_times=CASE WHEN payload ? 'pickup_times' THEN ARRAY(SELECT jsonb_array_elements_text(payload->'pickup_times')) ELSE pickup_times END,claim_emails=coalesce((payload->>'claim_emails')::boolean,claim_emails),message_emails=coalesce((payload->>'message_emails')::boolean,message_emails) WHERE id=auth.uid(); END IF; IF action IN('post','wish','edit_item') AND lower(payload->>'category')='other' THEN IF length(public.clean_text(payload->>'custom_category')) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'Custom categories must be 1–30 characters'; END IF; PERFORM set_config('passalong.custom_category',public.clean_text(payload->>'custom_category'),true); END IF; result=public.passalong_circle_action(action,payload); IF action='profile' THEN INSERT INTO public.events(user_id,name) VALUES(auth.uid(),'profile_updated'); END IF; RETURN result; END $$;
COMMENT ON COLUMN public.events.category_id IS 'Identifier only for custom-category usage or promotion; never attach free text';